async function playFailureTone(){if(!audioArmed||!armAudio())return false;try{await audioContext.resume();const now=audioContext.currentTime;[0,0.19,0.38].forEach((offset,index)=>{const oscillator=audioContext.createOscillator(),gain=audioContext.createGain();oscillator.type=index===1?"square":"sine";oscillator.frequency.setValueAtTime(index===1?330:220,now+offset);gain.gain.setValueAtTime(.0001,now+offset);gain.gain.exponentialRampToValueAtTime(.18,now+offset+.025);gain.gain.exponentialRampToValueAtTime(.0001,now+offset+.15);oscillator.connect(gain);gain.connect(audioContext.destination);oscillator.start(now+offset);oscillator.stop(now+offset+.17)});return true}catch(_){return false}}
