function renderFailure(){const alert=$("failure-alert"),failure=STATE.failure;if(!failure){alert.classList.add("hidden");return}const terminal=failure.severity==="error"||["escalated","error"].includes(STATE.status),stage={product:"Definición del producto",architect:"Arquitectura de la solución",planner:"Planificación del trabajo",dev_backend:"Desarrollo del servidor",dev_frontend:"Desarrollo de la interfaz",qa:"Control de calidad",human_gate:"Aprobación humana"}[failure.node]||failure.node||"Proceso";alert.className=`failure-alert ${terminal?"error":"warning"}`;$("failure-kicker").textContent=terminal?"Proceso bloqueado":"Corrección automática";$("failure-title").textContent=failure.user_title||(terminal?`${stage} necesita una corrección`:`${stage} está corrigiendo un problema`);$("failure-reason").textContent=failure.user_reason||"La revisión encontró información incompleta y no puede continuar todavía.";$("failure-impact").textContent=failure.user_impact||"El proceso se detuvo para evitar avanzar con un resultado que no puede comprobarse.";const meta=[["Etapa",stage],["Intentos realizados",failure.attempt]].filter(item=>item[1]);$("failure-meta").innerHTML=meta.map(item=>`<span>${esc(item[0])}: ${esc(item[1])}</span>`).join("");const findings=[...new Set(failure.user_findings||[])].filter(Boolean);$("failure-findings").innerHTML=findings.map(item=>`<li>${esc(item)}</li>`).join("");$("failure-action").innerHTML=`<b>Qué debe hacerse</b><span>${esc(failure.user_action||"Corrige la información indicada y vuelve a continuar desde este punto.")}</span>`;const technical=failure.technical||failure,technicalMeta=[["Agente",technical.node],["Gate",technical.gate],["Regla",technical.rule],["Ubicación",technical.location]].filter(item=>item[1]),technicalFindings=[...new Set(technical.findings||failure.findings||[])].filter(Boolean);$("failure-technical-meta").innerHTML=technicalMeta.map(item=>`<span>${esc(item[0])}: ${esc(item[1])}</span>`).join("");$("failure-technical-findings").innerHTML=technicalFindings.map(item=>`<li>${esc(item)}</li>`).join("");$("failure-technical").classList.toggle("hidden",!technicalMeta.length&&!technicalFindings.length);$("resume-failure").classList.toggle("hidden",!failure.can_resume);$("resume-failure").disabled=STATE.status==="running";$("replay-alert").classList.toggle("hidden",!terminal);const fingerprint=failure.id||`${failure.node}:${failure.gate}:${failure.reason}`;if(terminal&&fingerprint!==lastFailureId){lastFailureId=fingerprint;playFailureTone();toast(failure.user_title||`${stage} necesita una corrección`)}}
$("resume-failure").onclick=()=>{if(STATE?.project&&STATE?.task){armAudio();resumeTask(STATE.project,STATE.task)}};$("replay-alert").onclick=async()=>{armAudio();const played=await playFailureTone();toast(played?"Alerta sonora reproducida":"El navegador bloqueó el audio; vuelve a intentarlo")};
