function iterationArtifacts(){const items=STATE?.artifacts||[],node=selectedIteration()?.node,prefixes={product:["spec/10_product/"],architect:["spec/20_arch/"],planner:["spec/30_plan/"],dev_backend:["src/backend/"],dev_frontend:["src/frontend/"],qa:["tests/"]};return !node||!prefixes[node]?items:items.filter(item=>prefixes[node].some(prefix=>item.path.startsWith(prefix)))}
