 $("drawer-summary").innerHTML=`<div class="stat-grid"><div class="stat"><span>Estado</span><b>${esc(STATE_LABEL[agent.state]||agent.state||"idle")}</b></div><div class="stat"><span>Tier</span><b class="tier-badge">${esc(agent.tier||"sin clasificar")}${agent.escalated?" · escalado":""}</b></div><div class="stat"><span>Proveedor</span><b>${esc(agent.provider||"Automático")}</b></div><div class="stat"><span>Modelo</span><b>${esc(agent.model||def.model||"Automático")}</b></div></div><div class="notice" style="margin-top:12px">${esc(agent.selection_reason||"Selección proyectada por política")}${agent.fallback_reason?` · Fallback: ${esc(agent.fallback_reason)}`:""}</div><div class="tag-row" style="margin-top:12px">${(agent.tools||def.tools||[]).map(t=>`<span class="chip">${esc(t)}</span>`).join("")}</div>`;
 renderAgentLogs(agent.id);$("drawer-io").innerHTML=`<div class="eyebrow">Prompt base · ${esc(def.prompt_path||"custom")}</div><pre class="code-preview">${esc(def.prompt_base||"Sin prompt base")}</pre><div class="eyebrow" style="margin-top:14px">Complemento del operador</div><pre class="code-preview">${esc(def.prompt_addon||"Sin instrucciones adicionales")}</pre>`;$("drawer-memory").innerHTML='<div class="empty-state"><b>Sin eventos de memoria</b>El runtime actual no emite snapshots de memoria estructurados. Esta vista se activará cuando existan eventos memory.read y memory.write.</div>';
