function renderAgentLogs(id){const lines=(STATE.log||[]).filter(line=>line.includes(id)||!id);$("drawer-logs").innerHTML=`<div class="log-toolbar"><input id="log-filter" placeholder="Filtrar logs…"><select id="log-level"><option value="all">Todos</option><option value="error">Error</option><option value="warn">Warning</option><option value="info">Info</option></select><button class="ghost-btn" id="drawer-copy-log">Copiar</button></div><div class="log-stream" id="log-stream"></div>`;const paintLogs=()=>{const term=$("log-filter").value.toLowerCase(),level=$("log-level").value;$("log-stream").innerHTML=lines.filter(l=>(!term||l.toLowerCase().includes(term))&&(level==="all"||logClass(l)===level)).map(l=>`<span class="log-line ${logClass(l)}">${esc(l)}</span>`).join("")||'<span class="dim">Sin eventos coincidentes.</span>';$("log-stream").scrollTop=$("log-stream").scrollHeight};$("log-filter").oninput=paintLogs;$("log-level").onchange=paintLogs;$("drawer-copy-log").onclick=()=>copyText(lines.join("\n"));paintLogs()}
function logClass(line){if(/error|defecto|escalate|fallo/i.test(line))return"error";if(/reintento|revert|omitido|warning/i.test(line))return"warn";if(/aprobado|done|escrito|integrated/i.test(line))return"ok";if(/gate|agente|nodo/i.test(line))return"info";return""}
function openTaskTrace(taskId){const task=(STATE.sprint||[]).find(t=>t.id===taskId),agent=task?findAgent(task.node):null;SELECTED_AGENT=agent?.id||task?.node||"task";const drawer=$("drawer");drawer._returnFocus=document.activeElement;drawer.classList.add("open");drawer.removeAttribute("inert");drawer.setAttribute("aria-hidden","false");$("drawer-title").textContent=taskId;$("drawer-subtitle").textContent=task?.title||task?.node||"Traza de tarea";setDrawerTab("trace");fetchTrace(STATE.project,STATE.task,taskId);setTimeout(()=>$("drawer-close").focus(),0)}
async function fetchTrace(project,task,tid){const body=$("drawer-trace");body.innerHTML='<div class="empty-state"><b>Cargando traza</b>Consultando el journal de ciclo de vida…</div>';try{const r=await fetch(`/lifecycle?project=${encodeURIComponent(project||"")}&task=${encodeURIComponent(task||"")}&task_id=${encodeURIComponent(tid)}`),data=await r.json(),events=data.events||[],summary=data.summary||{},tokens=data.tokens||{};body.innerHTML=`<div class="stat-grid"><div class="stat"><span>Estado</span><b>${esc(summary.status||"?")}</b></div><div class="stat"><span>Eventos</span><b>${events.length}</b></div><div class="stat"><span>Llamadas</span><b>${summary.calls||0}</b></div><div class="stat"><span>Tokens</span><b>${fmt((tokens.input_tokens||0)+(tokens.output_tokens||0))}</b></div></div><div class="trace-list" style="margin-top:12px">${events.map(ev=>{const fail=ev.status==="fail"||["blocked","escalated"].includes(ev.event);return `<div class="trace-row ${fail?"fail":["done","integrated"].includes(ev.event)?"ok":""}"><b>${esc(ev.event||"evento")}</b><span>${esc(traceDetail(ev))} · ${esc((ev.t||"").slice(11,23))}</span></div>`}).join("")}</div>`}catch(e){body.innerHTML=`<div class="empty-state"><b>No se pudo cargar</b>${esc(e.message)}</div>`}}
function traceDetail(ev){if(ev.event==="gate_result")return `${ev.gate} · ${ev.status} · ${ev.findings||0} hallazgos`;if(ev.event==="blocked")return `Bloqueado por ${ev.blocked_by||"dependencia"}`;if(ev.event==="agent_called")return `returncode ${ev.returncode}`;if(ev.event==="model_selected")return `${ev.provider} · ${ev.model} · ${ev.tier}`;if(ev.event==="model_escalated")return `${ev.gate} · frontier · escalado ${ev.count}`;return ev.detail||ev.reason||ev.node||"evento registrado"}

