async function loadCfg(){const c=await fetch("/config").then(r=>r.json());CFG={...c,keys:{},key_status:c.key_status||{},agents:c.agents||[],agent_profiles:c.agent_profiles||{},custom_agents:c.custom_agents||[],model_choices:c.model_choices||{}};$("output-base").value=CFG.output_base||"project";$("theme").value=CFG.theme||"auto";applyTheme(CFG.theme||"auto");$("provider").value=CFG.provider||"anthropic";fillModels("provider-model",$("provider").value,CFG.model);$("provider-key").value="";$("provider-key").placeholder=CFG.key_status[$("provider").value]?"Credencial guardada · escribe para reemplazar":"API key requerida";const routing=CFG.routing||{},review=routing.reviewer||{};if($("routing-mode"))$("routing-mode").value=routing.mode||"adaptive";if($("review-provider"))$("review-provider").value=review.provider||"";if($("review-model"))$("review-model").value=review.model||"";if($("review-diversity"))$("review-diversity").checked=review.prefer_different_provider!==false;await loadRoutingPreview();renderAgentRegistry();syncRunForm()}function fillModels(id,provider,selected){const el=$(id),models=CFG.model_choices?.[provider]||[];el.innerHTML=(models.length?models:[""]).map(m=>`<option value="${esc(m)}">${esc(m||"Modelo definido por entorno")}</option>`).join("");if(selected&&models.includes(selected))el.value=selected}
