function renderAgentRegistry(){const term=($("agent-search")?.value||"").toLowerCase(),agents=(CFG.agents||[]).filter(a=>!term||`${a.name} ${a.id} ${a.role}`.toLowerCase().includes(term));$("agent-list").innerHTML=agents.map(a=>`<div class="registry-item ${SELECTED_AGENT===a.id?"active":""}" data-edit-agent="${esc(a.id)}"><div class="agent-avatar">${initials(a.name)}</div><div><b>${esc(a.name)}</b><span>${esc(a.id)} · ${esc(a.model||"modelo global")}</span></div><button class="switch ${a.enabled!==false?"on":""}" data-toggle-agent="${esc(a.id)}" aria-label="Activar o desactivar ${esc(a.name)}"><i></i></button></div>`).join("");qa("[data-edit-agent]").forEach(el=>el.onclick=e=>{if(e.target.closest("[data-toggle-agent]"))return;SELECTED_AGENT=el.dataset.editAgent;renderAgentRegistry();renderAgentEditor()});qa("[data-toggle-agent]").forEach(b=>b.onclick=async e=>{e.stopPropagation();const a=agentDefinition(b.dataset.toggleAgent);await persistAgent(a,{enabled:a.enabled===false});toast(a.enabled===false?"Agente activado":"Agente desactivado")});if(!SELECTED_AGENT&&agents[0])SELECTED_AGENT=agents[0].id;renderAgentEditor()}
