 <div class="editor-panel" id="editor-tools"><div class="tool-grid">${tools.map(t=>`<label class="tool-option"><input type="checkbox" data-tool="${esc(t)}" ${(a.tools||[]).includes(t)?"checked":""}>${esc(t)}</label>`).join("")}</div></div>
