async function saveAgentEditor(){const a=agentDefinition(SELECTED_AGENT),patch={enabled:$("agent-enabled").value==="true",provider:$("agent-provider").value,model:$("agent-model").value,temperature:Number($("agent-temperature").value),max_tokens:Number($("agent-max-tokens").value)||0,system_prompt:$("agent-system-prompt").value,prompt_addon:$("agent-addon").value,tools:qa("[data-tool]:checked").map(x=>x.dataset.tool)};if(!a.built_in){a.name=$("agent-name").value;a.role=$("agent-role").value}await persistAgent(a,patch);toast("Agente guardado")}
