async function exportAgentBundle(){const data=await fetch("/agent-bundle").then(r=>r.json()),blob=new Blob([JSON.stringify(data,null,2)],{type:"application/json"}),url=URL.createObjectURL(blob),a=document.createElement("a");a.href=url;a.download="autoscrum-agent-bundle.json";a.click();URL.revokeObjectURL(url);toast("Configuración exportada")}
async function importAgentBundle(file){try{const data=JSON.parse(await file.text()),profiles=data.agents||data.agent_profiles;if(!profiles||typeof profiles!=="object"||Array.isArray(profiles))throw new Error("El bundle no contiene agentes válidos");const patch={agent_profiles:profiles};if(Array.isArray(data.custom_agents))patch.custom_agents=data.custom_agents;await saveConfig(patch);await loadCfg();toast(`${Object.keys(profiles).length} agentes importados`)}catch(e){toast(e.message||"No se pudo importar")}finally{$("agent-bundle-file").value=""}}
$("import-agents").onclick=()=>$("agent-bundle-file").click();$("agent-bundle-file").onchange=e=>{const file=e.target.files?.[0];if(file)importAgentBundle(file)};$("export-agents").onclick=exportAgentBundle;
$("create-agent").onclick=()=>openModal("create-modal");$("confirm-create-agent").onclick=async()=>{const id=slug($("new-agent-id").value),name=$("new-agent-name").value.trim()||id,role=$("new-agent-role").value.trim()||"Custom agent";if(!id||id==="sin-nombre"){toast("Define un identificador");return}if((CFG.agents||[]).some(a=>a.id===id)){toast("Ese agente ya existe");return}const custom=[...(CFG.custom_agents||[]),{id,name,role,prompt_base:"",writes:[],gates:[]}];await saveConfig({custom_agents:custom,agent_profiles:{[id]:{enabled:true,temperature:.2,max_tokens:0,system_prompt:"",prompt_addon:"",tools:["filesystem"]}}});closeModal("create-modal");SELECTED_AGENT=id;await loadCfg();renderAgentRegistry();toast("Agente creado")};

async function loadProjects(){const list=await fetch("/projects").then(r=>r.json()),sel=$("history-project"),cur=sel.value;sel.innerHTML=list.length?list.map(p=>`<option value="${esc(p)}">${esc(p)}</option>`).join(""):'<option value="">Sin proyectos</option>';if(list.includes(cur))sel.value=cur;await loadTasks()}
async function loadTasks(){const project=$("history-project").value;if(!project){$("history-tasks").innerHTML='<div class="empty-state"><b>Sin proyectos</b>Inicia una ejecución.</div>';return}const list=await fetch(`/tasks?project=${encodeURIComponent(project)}`).then(r=>r.json());$("history-tasks").innerHTML=list.map(t=>{const pct=Math.round(100*t.done/Math.max(t.total,1)),resume=["escalated","waiting_human","running"].includes(t.final);return `<article class="task-card" data-history-task="${esc(t.task)}"><div class="task-card-head"><b>${esc(t.task)}</b><span class="status-pill ${esc(t.final)}">${esc(t.final)}</span></div><div class="progress"><i style="width:${pct}%"></i></div><div class="task-meta">${t.done}/${t.total} ${esc(t.unit||"nodos")} · ${t.calls} llamadas</div>${resume?`<button class="ghost-btn" data-resume="${esc(t.task)}" style="margin-top:12px">Continuar</button>`:""}</article>`}).join("")||'<div class="empty-state"><b>Sin ejecuciones</b>Este proyecto aún no tiene runs.</div>';qa("[data-history-task]").forEach(card=>card.onclick=e=>{if(e.target.closest("[data-resume]"))return;viewTask(project,card.dataset.historyTask)});qa("[data-resume]").forEach(b=>b.onclick=()=>resumeTask(project,b.dataset.resume))}
$("history-project").onchange=loadTasks;$("refresh-history").onclick=loadProjects;
async function viewTask(project,task){SOURCE="history";const data=await fetch(`/task?project=${encodeURIComponent(project)}&task=${encodeURIComponent(task)}`).then(r=>r.json());SELECTED_ITERATION=null;paint(data);showView("workspace")}
async function resumeTask(project,task,decision,feedback=""){armAudio();const buttons=[$("resume-failure"),$("accept-review"),$("reject-review")].filter(Boolean);buttons.forEach(button=>button.disabled=true);try{const body={project,task};if(decision)Object.assign(body,{decision,feedback});const r=await fetch("/resume",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify(body)}),data=await r.json();if(!r.ok){toast(data.error||"No se pudo continuar");return}SOURCE="live";SELECTED_ITERATION=null;showView("workspace");await fetchState();toast(`Ejecución reanudada desde ${LIVE_STATE?.activity?.node||LIVE_STATE?.raw?.resume_checkpoint?.from_node||"el punto de fallo"}`)}finally{buttons.forEach(button=>button.disabled=false)}}

function pathPreview(){if(!$("project"))return;$("path-preview").textContent=`${$("output-base").value||CFG.output_base||"project"}/${slug($("project").value)}/${slug($("task").value||"tarea-1")}`}
["project","task"].forEach(id=>$(id).oninput=pathPreview);["new-run","new-run-rail"].forEach(id=>$(id).onclick=()=>{syncRunForm();openModal("run-modal")});
$("go").onclick=async()=>{syncIdeaValue();const project=$("project").value.trim(),idea=$("idea").value.trim(),provider=$("run-provider").value,key=$("run-key").value;if(!project){toast("Define el proyecto");return}if(!idea){toast("Describe el objetivo");return}if(!key&&!Object.values(CFG.key_status||{}).some(Boolean)){toast("Configura al menos una API key");return}const button=$("go");button.disabled=true;$("gotxt").textContent="Iniciando…";try{const r=await fetch("/run",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({idea,provider,model:$("model").value,key,project,task:$("task").value})}),data=await r.json();if(!r.ok)throw new Error(data.error||"No se pudo iniciar");closeModal("run-modal");SOURCE="live";SELECTED_ITERATION=null;showView("workspace");await fetchState();toast("Workflow iniciado")}catch(e){toast(e.message)}finally{button.disabled=false;$("gotxt").textContent="Iniciar workflow"}};
function stopBtn(){$("go").disabled=false;$("gotxt").textContent="Iniciar workflow"}

function connection(live,text){const el=$("connection");el.classList.toggle("live",live);q("span",el).textContent=text}
function acceptLiveState(state,source){LIVE_STATE=state;lastEventAt=Date.now();if(SOURCE==="live")paint(state);connection(true,source==="sse"?"En vivo · SSE":"En vivo · reconciliado")}
async function fetchState(){try{const response=await fetch(`/state?_=${Date.now()}`,{cache:"no-store"});if(!response.ok)throw new Error(`HTTP ${response.status}`);acceptLiveState(await response.json(),"poll")}catch(_){connection(false,"Runtime no disponible")}}
function connectStream(){clearInterval(pollTimer);pollTimer=setInterval(fetchState,1200);fetchState();if(!window.EventSource)return;eventSource?.close();eventSource=new EventSource("/events");eventSource.addEventListener("state",event=>{try{acceptLiveState(JSON.parse(event.data),"sse")}catch(_){connection(false,"Evento inválido")}});eventSource.onopen=()=>connection(true,"En vivo · SSE");eventSource.onerror=()=>{connection(false,"Reconectando SSE…");fetchState()};setInterval(()=>{if(Date.now()-lastEventAt>3500)fetchState()},2000)}
$("live-run-card").onclick=()=>{SOURCE="live";SELECTED_ITERATION=null;if(LIVE_STATE)paint(LIVE_STATE);showView("workspace")};
function legacyCopy(text){const a=document.createElement("textarea");a.value=text;a.setAttribute("readonly","");a.style.position="fixed";a.style.opacity="0";document.body.appendChild(a);a.select();try{return document.execCommand("copy")}finally{a.remove()}}
async function copyText(text){try{if(navigator.clipboard&&window.isSecureContext)await navigator.clipboard.writeText(text);else if(!legacyCopy(text))throw new Error("copy");toast("Copiado al portapapeles")}catch(_){toast("No se pudo copiar")}}
async function copyLog(){const LOG_LINES=STATE?.log||[];return copyText(LOG_LINES.join("\n"))}$("copylog").onclick=copyLog;

(async function init(){mountRunComposer();await loadCfg();fetch("/idea").then(r=>r.text()).then(t=>{if(t&&!$("idea").value){$("idea").value=t;setIdeaContent(t)}});await fetchState();connectStream();const initial=(location.hash||"#workspace").slice(1);showView(["workspace","history","results","settings"].includes(initial)?initial:"workspace")})();
